def log_error(msg: str):
    print(f"\n\033[31m[错误] {msg}\033[0m", file=sys.stderr)


def log_warning(msg: str):
    print(f"\n\033[33m[警告] {msg}\033[0m")


def log_success(msg: str):
    print(f"\033[32m{msg}\033[0m")


def load_auth_cache() -> dict:
    if not os.path.exists(AUTH_CACHE_FILE):
        return {}
    try:
        with open(AUTH_CACHE_FILE, "r", encoding="utf-8") as f:
            return json.load(f)
    except (json.JSONDecodeError, IOError):
        return {}


def ensure_auth() -> dict:
    """优先复用已登录缓存，首次使用时自动触发统一登录流程"""
    auth = load_auth_cache()
    if not auth.get("loggedIn") or not auth.get("token"):
        print("未检测到登录态，正在启动登录流程...")
        from . import cmd_login
        return cmd_login.ensure_login()

    username = auth.get("username", "")
    token = auth.get("token", "")

    # 校验缓存 token 是否仍有效，失效则重新登录
    try:
        from .secure_api import activate_token
        result = activate_token(token)
        # 接口返回 {code: 0, msg: ...}，非 0 视为失效
        if result.get("code") != 0:
            print("登录态已失效，正在重新登录...")
            from . import cmd_login
            return cmd_login.ensure_login()
    except Exception:
        pass

    # 获取模型信息（需要 username 调用接口）
    try:
        from .secure_api import get_model_info
        model_info = get_model_info(username, purpose="Claude Code")
        models_data = [
            {"model_id": model_id, "model_name": model_info.get("model_names", {}).get(model_id, model_id)}
            for model_id in model_info.get("models", [])
        ]
        if not models_data:
            raise RuntimeError("没有可用模型")
    except Exception as e:
        log_error(f"获取模型信息失败: {e}")
        sys.exit(1)

    models = [m["model_id"] for m in models_data]
    model_names = {m["model_id"]: m["model_name"] for m in models_data}

    return {
        "username": username,
        "token": token,
        "api_key": token,
        "model": models[0],
        "models": models,
        "model_names": model_names,
        "model_caps": model_info.get("model_caps", {}),
    }


def get_ahclaude_cmd():
    import shutil

    cmd = shutil.which("auto++")
    if cmd:
        return f'"{cmd}"'

    python_exec = sys.executable
    return f'"{python_exec}" -m ahclaude_plugin'


def safe_chmod(path: str, mode: int):
    """Unix 设置文件权限，Windows 上静默跳过"""
    try:
        os.chmod(path, mode)
    except OSError:
        pass  # Windows 不支持，跳过



def _set_windows_user_env(key: str, value: str):
    """Windows 下持久化写入用户环境变量，供 Codex 桌面端直接读取"""
    # 先写当前进程环境，让本次安装后立刻启动的 Codex 能读到。
    os.environ[key] = value
    os.putenv(key, value)

    try:
        subprocess.run(
            ["setx", key, value],
            check=True,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.PIPE,
            text=True,
        )
    except FileNotFoundError as e:
        raise RuntimeError("未找到 setx，无法写入 Windows 用户环境变量") from e
    except subprocess.CalledProcessError as e:
        error_msg = (e.stderr or "").strip() or "未知错误"
        raise RuntimeError(f"写入 Windows 用户环境变量失败: {error_msg}") from e



def create_directory():
    try:
        os.makedirs(CODEX_DIR, exist_ok=True)
    except PermissionError:
        log_error(f"无权限创建目录: {CODEX_DIR}")
        raise
    except OSError as e:
        log_error(f"创建目录失败: {e}")
        raise


def load_toml_raw() -> str:
    if os.path.exists(CODEX_CONFIG_FILE):
        try:
            with open(CODEX_CONFIG_FILE, "r", encoding="utf-8") as f:
                return f.read()
        except IOError:
            return ""
    return ""


def save_toml_raw(content: str):
    try:
        backup_existing_file(CODEX_CONFIG_FILE, "Codex config.toml", content)
        with open(CODEX_CONFIG_FILE, "w", encoding="utf-8") as f:
            f.write(content)
    except IOError as e:
        log_error(f"保存 config.toml 失败: {e}")
        raise


def _remove_ahclaude_sections(content: str) -> str:
    """移除已有的 ahclaude 注入块（# BEGIN auto++ ... # END auto++）"""
    lines = content.split("\n")
    result = []
    skip = False
    for line in lines:
        if line.strip() == "# BEGIN auto++":
            skip = True
            continue
        if line.strip() == "# END auto++":
            skip = False
            continue
        if not skip:
            result.append(line)
    while result and result[-1].strip() == "":
        result.pop()
    return "\n".join(result)


def _remove_section(content: str, section_name: str) -> str:
    """移除指定的 [section] 及其所有子节（含 section_name.xxx 形式）"""
    # 提取裸名，如 [model_providers.autohome] -> model_providers.autohome
    bare = section_name.strip("[]")
    lines = content.split("\n")
    result = []
    skip = False
    for line in lines:
        stripped = line.strip()
        if stripped.startswith("[") and stripped.endswith("]"):
            inner = stripped.strip("[]")
            # 匹配本节或其子节（如 model_providers.autohome.auth）
            if inner == bare or inner.startswith(bare + "."):
                skip = True
                continue
            else:
                skip = False
        if not skip:
            result.append(line)
    return "\n".join(result)


def _set_toplevel_keys(content: str, keys: dict) -> str:
    """覆盖或插入顶层 key = "value" 行，必须在任何 [section] 之前"""
    lines = content.split("\n")

    # 先删除已有的同名顶层 key（只处理 [section] 之前的行）
    in_section = False
    result = []
    for line in lines:
        stripped = line.strip()
        if stripped.startswith("[") and not stripped.startswith("[["):
            in_section = True
        if not in_section:
            key_name = stripped.split("=")[0].strip()
            if key_name in keys:
                continue  # 删除旧值
        result.append(line)

    # 找到第一个 [section] 的位置，在它之前插入新的顶层 key
    insert_pos = 0
    for i, line in enumerate(result):
        stripped = line.strip()
        if stripped.startswith("[") and not stripped.startswith("[["):
            insert_pos = i
            break
    else:
        insert_pos = len(result)

    # 去掉开头多余空行
    while result and result[0].strip() == "":
        result.pop(0)
        insert_pos = max(0, insert_pos - 1)

    new_lines = [f'{k} = "{v}"' for k, v in keys.items()]
    result = result[:insert_pos] + new_lines + [""] + result[insert_pos:]

    return "\n".join(result)


def _set_section_bool_key(content: str, section_name: str, key: str, value: bool) -> str:
    """覆盖或插入 [section] 下的布尔配置，保留同节其他用户配置"""
    bare = section_name.strip("[]")
    lines = content.split("\n")
    result = []
    in_target = False
    section_found = False
    key_written = False
    value_text = "true" if value else "false"

    for line in lines:
        stripped = line.strip()
        if stripped.startswith("[") and stripped.endswith("]"):
            if in_target and not key_written:
                result.append(f"{key} = {value_text}")
                key_written = True
            inner = stripped.strip("[]")
            in_target = inner == bare
            section_found = section_found or in_target

        if in_target:
            key_name = stripped.split("=")[0].strip()
            if key_name == key:
                if not key_written:
                    result.append(f"{key} = {value_text}")
                    key_written = True
                continue

        result.append(line)

    if in_target and not key_written:
        result.append(f"{key} = {value_text}")

    if not section_found:
        while result and result[-1].strip() == "":
            result.pop()
        if result:
            result.append("")
        result.extend([section_name, f"{key} = {value_text}"])

    return "\n".join(result)


def _remove_section_key(content: str, section_name: str, key: str) -> str:
    """从 [section] 中删除指定 key，其他内容保持不变"""
    bare = section_name.strip("[]")
    lines = content.split("\n")
    result = []
    in_target = False
    for line in lines:
        stripped = line.strip()
        if stripped.startswith("[") and stripped.endswith("]"):
            in_target = stripped.strip("[]") == bare
        if in_target and stripped.split("=")[0].strip() == key:
            continue
        result.append(line)
    return "\n".join(result)


def _detect_shell_rc() -> str:
    """检测用户当前 shell 对应的 rc 文件"""
    shell = os.environ.get("SHELL", "")
    if "zsh" in shell:
        return os.path.expanduser("~/.zshrc")
    if "fish" in shell:
        return os.path.expanduser("~/.config/fish/config.fish")
    return os.path.expanduser("~/.bashrc")


def _write_export_to_shellrc(rc_file: str, key: str, value: str):
    """在 shell rc 文件中更新 export KEY=VALUE，幂等"""
    marker_begin = f"# BEGIN auto++ {key}"
    marker_end = f"# END auto++ {key}"

    lines = []
    if os.path.exists(rc_file):
        try:
            with open(rc_file, "r", encoding="utf-8") as f:
                lines = f.readlines()
        except IOError:
            lines = []

    # 移除旧块
    result = []
    skip = False
    for line in lines:
        if line.strip() == marker_begin:
            skip = True
            continue
        if line.strip() == marker_end:
            skip = False
            continue
        if not skip:
            result.append(line)

    # 末尾补换行后追加新块
    if result and not result[-1].endswith("\n"):
        result.append("\n")

    if "fish" in rc_file:
        export_line = f"set -gx {key} \"{value}\"\n"
    else:
        export_line = f"export {key}=\"{value}\"\n"

    result.append(f"\n{marker_begin}\n{export_line}{marker_end}\n")
    new_content = "".join(result)

    os.makedirs(os.path.dirname(rc_file) if os.path.dirname(rc_file) else ".", exist_ok=True)
    backup_existing_file(rc_file, os.path.basename(rc_file) or "shell rc", new_content)
    with open(rc_file, "w", encoding="utf-8") as f:
        f.write(new_content)


def _remove_export_from_shellrc(rc_file: str, key: str):
    """从 shell rc 文件中移除 auto++ 注入的 export 块"""
    if not os.path.exists(rc_file):
        return
    marker_begin = f"# BEGIN auto++ {key}"
    marker_end = f"# END auto++ {key}"
    with open(rc_file, "r", encoding="utf-8") as f:
        lines = f.readlines()
    result = []
    skip = False
    for line in lines:
        if line.strip() == marker_begin:
            skip = True
            continue
        if line.strip() == marker_end:
            skip = False
            continue
        if not skip:
            result.append(line)
    new_content = "".join(result)
    backup_existing_file(rc_file, os.path.basename(rc_file) or "shell rc", new_content)
    with open(rc_file, "w", encoding="utf-8") as f:
        f.write(new_content)


def _is_auto_command(command: str) -> bool:
    if not command:
        return False
    return "ahclaude_plugin" in command or "auto++" in command


def _clean_old_providers(content: str) -> str:
    """清理非 autohome 的 model_providers 块，保留 marketplaces（供插件使用）"""
    lines = content.split("\n")
    result = []
    skip = False
    for line in lines:
        stripped = line.strip()
        # 只删除非 autohome 的 model_providers 段，不动 marketplaces
        if stripped.startswith("[model_providers.") and stripped != f"[model_providers.{PROVIDER_ID}]":
            skip = True
            continue
        # 段内遇到新的 [ 开头的段，退出 skip
        if skip and stripped.startswith("[") and stripped.endswith("]"):
            skip = False
        if not skip:
            result.append(line)
    return "\n".join(result)


def _clean_ahclaude_hooks(hooks_data: dict):
    """从 hooks.json 中移除 auto++ 相关的 hook 条目"""
    if "hooks" not in hooks_data:
        return
    for event in list(hooks_data["hooks"].keys()):
        hooks_data["hooks"][event] = [
            entry for entry in hooks_data["hooks"][event]
            if not any(
                _is_auto_command(h.get("command", ""))
                for h in entry.get("hooks", [])
            )
        ]
        if not hooks_data["hooks"][event]:
            del hooks_data["hooks"][event]
    if not hooks_data.get("hooks"):
        hooks_data.pop("hooks", None)


def configure_hooks_json(ahclaude_cmd: str):
    """写入 ~/.codex/hooks.json，格式：{ "hooks": { "EventName": [...] } }"""
    hooks_data = {}
    if os.path.exists(HOOKS_FILE):
        try:
            with open(HOOKS_FILE, "r", encoding="utf-8") as f:
                hooks_data = json.load(f)
        except (json.JSONDecodeError, IOError):
            pass

    _clean_ahclaude_hooks(hooks_data)
    if "hooks" not in hooks_data:
        hooks_data["hooks"] = {}

    if sys.platform == "win32":
        def wrap_hook_cmd(subcommand: str) -> str:
            # ahclaude_cmd 已含外层引号，如 "C:\path\auto++.exe"
            # cmd /s /c "..." 会去掉首尾的 "，剩下 "C:\path\auto++.exe" <subcommand>
            return f'cmd.exe /d /s /c "{ahclaude_cmd} {subcommand} >NUL 2>&1"'
    else:
        def wrap_hook_cmd(subcommand: str) -> str:
            return f"{ahclaude_cmd} {subcommand} >/dev/null 2>&1"

    def wrap_hook_item(subcommand: str) -> dict:
        return {
            "type": "command",
            "command": wrap_hook_cmd(subcommand),
        }

    def append_hook_entry(event_name: str, entry: dict):
        """同级追加 hook，避免覆盖 oh-my-codex 等其他工具已注册的同事件 hooks。"""
        event_hooks = hooks_data["hooks"].get(event_name, [])
        event_hooks.append(entry)
        hooks_data["hooks"][event_name] = event_hooks

    # Codex 会把 hook stdout 展示到会话中；重定向输出，避免干扰用户对话。
    # 注意：所有事件都采用“清理 auto++ 旧项后追加”的策略，保留其他工具 hook。
    # SessionStart: 记录会话启动，不覆盖其他 startup/resume hook。
    append_hook_entry("SessionStart", {
        "matcher": "startup|resume",
        "hooks": [wrap_hook_item("codex start")]
    })

    # UserPromptSubmit: 用户提交 prompt 时触发，不覆盖同级 prompt hook。
    append_hook_entry("UserPromptSubmit", {
        "hooks": [wrap_hook_item("codex prompt")]
    })

    # PreToolUse: 工具执行（紧接的模型请求）前重新激活 token，
    # 避免审批弹窗久未确认导致 key 失活后请求报错。
    append_hook_entry("PreToolUse", {
        "hooks": [wrap_hook_item("codex activate")]
    })

    # Stop: Codex 的 apply_patch 不触发 PostToolUse，这里在回合结束后解析 transcript 上报 diff。
    append_hook_entry("Stop", {
        "hooks": [wrap_hook_item("codex stop")]
    })

    new_content = json.dumps(hooks_data, ensure_ascii=False, indent=2)
    # 幂等：内容未变时不写文件，避免触发 Codex 重新校验 trusted_hash
    if os.path.exists(HOOKS_FILE):
        try:
            with open(HOOKS_FILE, "r", encoding="utf-8") as f:
                existing = f.read()
            if existing == new_content:
                return
        except IOError:
            pass
    backup_existing_file(HOOKS_FILE, "Codex hooks.json", new_content)
    with open(HOOKS_FILE, "w", encoding="utf-8") as f:
        f.write(new_content)


def _parse_codex_catalog() -> tuple[dict, dict]:
    """从 Codex 二进制提取内置 catalog，返回 (template, slug_index)。
    template: 第一个模型的字段作为克隆模板
    slug_index: {slug: model_data} 用于按 slug 查询内置字段（如 reasoning levels）
    """
    import shutil
    codex_bin = shutil.which("codex") or "/Applications/Codex.app/Contents/Resources/codex"
    if not os.path.exists(codex_bin):
        return {}, {}
    try:
        with open(codex_bin, "rb") as f:
            data = f.read()
        marker = b'{"models":['
        idx = data.find(marker)
        if idx < 0:
            marker = b'{\n  "models": ['
            idx = data.find(marker)
        if idx < 0:
            return {}, {}
        chunk = data[idx:idx + 500000].decode("latin-1", errors="replace")
        depth, end, in_str, escape = 0, 0, False, False
        for i, c in enumerate(chunk):
            if escape:
                escape = False
                continue
            if c == "\\" and in_str:
                escape = True
                continue
            if c == '"' and not escape:
                in_str = not in_str
                continue
            if in_str:
                continue
            if c in "{[":
                depth += 1
            elif c in "}]":
                depth -= 1
                if depth == 0:
                    end = i + 1
                    break
        catalog = json.loads(chunk[:end])
        models = catalog.get("models", [])
        template = models[0] if models else {}
        slug_index = {m["slug"]: m for m in models if "slug" in m}
        return template, slug_index
    except Exception:
        return {}, {}



_TEXT_ONLY_MODEL_PREFIXES = ("minimax",)

_GPT_REASONING_LEVELS = [
    {"effort": "low",    "description": "Fast responses with lighter reasoning"},
    {"effort": "medium", "description": "Balances speed and reasoning depth for everyday tasks"},
    {"effort": "high",   "description": "Greater reasoning depth for complex problems"},
    {"effort": "xhigh",  "description": "Extra high reasoning depth for complex problems"},
]

# GPT 模型与 Claude 在多个技术字段上不同，需要单独覆盖
_GPT_TECH_OVERRIDES = {
    "apply_patch_tool_type": "freeform",
    "support_verbosity": True,
    "supports_reasoning_summaries": True,
    "supports_search_tool": True,
    "context_window": 272000,
    "max_context_window": 1000000,
    "effective_context_window_percent": 95,
}


def _gpt_reasoning_levels(model_id: str) -> tuple[list, str]:
    """GPT 系列模型返回固定的思考强度选项；其他模型返回空列表。"""
    mid = model_id.lower()
    if mid.startswith("gpt") or "codex-auto" in mid:
        return _GPT_REASONING_LEVELS, "medium"
    return [], "medium"


def _codex_model_supports_images(model_id: str) -> bool:
    mid = model_id.lower()
    return not any(mid.startswith(p) or p in mid for p in _TEXT_ONLY_MODEL_PREFIXES)


def write_model_catalog(login_info: dict):
    """生成 ~/.codex/model-catalogs/autohome.json 供 Codex 桌面端展示模型列表"""
    models_data = login_info.get("models", [])
    model_names = login_info.get("model_names", {})

    # 从 Codex 二进制提取真实字段模板，保证 schema 100% 兼容
    template, _ = _parse_codex_catalog()

    catalog_models = []
    for model_id in models_data:
        display_name = model_names.get(model_id, model_id)
        supports_images = _codex_model_supports_images(model_id)
        input_modalities = ["text", "image"] if supports_images else ["text"]
        supported_reasoning_levels, default_reasoning_level = _gpt_reasoning_levels(model_id)
        if template:
            # 用真实模板克隆，只替换业务字段
            m = dict(template)
            m["slug"] = model_id
            m["display_name"] = display_name
            m["description"] = ""
            m["base_instructions"] = ""
            m["model_messages"] = {
                "instructions_template": "",
                "instructions_variables": {
                    "personality_default": "",
                    "personality_friendly": "",
                    "personality_pragmatic": "",
                },
            }
            m["availability_nux"] = None
            m["upgrade"] = None
            m["priority"] = 0
            m["supported_reasoning_levels"] = supported_reasoning_levels
            m["default_reasoning_level"] = default_reasoning_level
            m["available_in_plans"] = []
            m["minimal_client_version"] = "0.1.0"
            m["input_modalities"] = input_modalities
            m["supports_image_detail_original"] = supports_images
        else:
            # fallback: 仅保留最小必需字段（可能不完整）
            m = {
                "slug": model_id,
                "display_name": display_name,
                "description": "",
                "shell_type": "shell_command",
                "visibility": "list",
                "supported_in_api": True,
                "availability_nux": None,
                "upgrade": None,
                "priority": 0,
                "base_instructions": "",
                "model_messages": {
                    "instructions_template": "",
                    "instructions_variables": {
                        "personality_default": "",
                        "personality_friendly": "",
                        "personality_pragmatic": "",
                    },
                },
                "prefer_websockets": True,
                "support_verbosity": False,
                "default_verbosity": "low",
                "apply_patch_tool_type": "freeform",
                "web_search_tool_type": "text_and_image",
                "input_modalities": input_modalities,
                "supports_image_detail_original": supports_images,
                "truncation_policy": {"mode": "tokens", "limit": 10000},
                "supports_parallel_tool_calls": True,
                "context_window": 200000,
                "max_context_window": 200000,
                "auto_compact_token_limit": None,
                "reasoning_summary_format": "experimental",
                "default_reasoning_summary": "none",
                "default_reasoning_level": default_reasoning_level,
                "supported_reasoning_levels": supported_reasoning_levels,
                "minimal_client_version": "0.1.0",
                "experimental_supported_tools": [],
                "available_in_plans": [],
                "supports_search_tool": False,
                "additional_speed_tiers": [],
                "supports_reasoning_summaries": False,
                "service_tiers": [],
            }
        m["apply_patch_tool_type"] = "freeform"
        if supported_reasoning_levels:
            m.update(_GPT_TECH_OVERRIDES)
        catalog_models.append(m)

    os.makedirs(MODEL_CATALOG_DIR, exist_ok=True)
    with open(MODEL_CATALOG_FILE, "w", encoding="utf-8") as f:
        json.dump({"models": catalog_models}, f, ensure_ascii=False, indent=2)


def _write_auth_json(api_key: str):
    """写入 ~/.codex/auth.json，格式兼容 Codex 26.513+ 的 requires_openai_auth 机制

    关键：必须清掉残留的 ChatGPT OAuth `tokens` 块。oh-my-codex 或历史 codex
    login 会在 auth.json 写入 OAuth tokens；当 requires_openai_auth = true 时
    Codex 会优先用 tokens.access_token 发请求，导致发出的 key 不是我们下发的
    autohome sk- key，服务端校验失败。这里整体覆盖，只保留 OPENAI_API_KEY。
    """
    # 显式 auth_mode=apikey，与 `codex login --with-api-key` 产物一致，
    # 把 Codex AuthManager 钉在 apikey 模式，杜绝 chatgpt 还原。
    auth_data = {"auth_mode": "apikey", "OPENAI_API_KEY": api_key.strip()}

    with open(AUTH_JSON_FILE, "w", encoding="utf-8") as f:
        json.dump(auth_data, f, ensure_ascii=False, indent=2)
    safe_chmod(AUTH_JSON_FILE, 0o600)


def _force_codex_apikey_auth(api_key: str):
    """通过 codex CLI 把登录态强制切到 API-key 模式。

    根因：用户若用 ChatGPT/Google 登录过 codex，Codex 的 AuthManager 会
    持久化该登录态，每次启动用 refresh_token 刷新并把 auth.json 写回
    auth_mode=chatgpt + tokens —— 此时 Codex 用 OAuth access_token 发请求，
    完全忽略我们写入的 OPENAI_API_KEY。仅在安装时覆盖 auth.json 会被 Codex
    下次启动还原。这里调用官方命令清除 ChatGPT 登录态并切到 apikey 模式。
    """
    import shutil

    codex_bin = shutil.which("codex")
    if codex_bin:
        try:
            # 清除已存储的 ChatGPT 凭据，停止后台 token 刷新与还原
            subprocess.run(
                [codex_bin, "logout"],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                timeout=15,
                check=False,
            )
            # 官方方式写入 API key，AuthManager 会把 auth_mode 固定为 apikey
            subprocess.run(
                [codex_bin, "login", "--with-api-key"],
                input=api_key.strip(),
                text=True,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                timeout=20,
                check=False,
            )
        except (subprocess.TimeoutExpired, OSError):
            pass

    # 兜底：无论 codex CLI 是否存在 / 成功，都必须确保 auth.json 为纯 apikey 形态。
    # 修复曾有 bug：CLI 不在 PATH 时早返回导致 auth.json 完全没生成。
    _write_auth_json(api_key)


def configure_codex(login_info: dict):
    """写入 model/provider/hooks 到 ~/.codex，API key 写入 auth.json。

    该函数也用于 `auto++ codex model` 后的自愈刷新：即使用户手工删除或篡改
    hooks.json/model catalog/config.toml，重新选择模型也会把 Codex hooks 写回去。
    """
    create_directory()
    api_key = login_info["api_key"]
    model = login_info["model"]
    ahclaude_cmd = get_ahclaude_cmd()

    # Codex 26.513+ 新机制：API key 写入 ~/.codex/auth.json 的 OPENAI_API_KEY 字段。
    # 同时清除 ChatGPT 登录态并强制 apikey 模式，避免 Codex 启动时还原 chatgpt。
    _force_codex_apikey_auth(api_key)

    # 同时保留旧的 api_key.txt（向下兼容旧版 Codex）
    os.makedirs(os.path.dirname(API_KEY_FILE), exist_ok=True)
    with open(API_KEY_FILE, "w", encoding="utf-8") as f:
        f.write(api_key.strip())
    safe_chmod(API_KEY_FILE, 0o600)
    if sys.platform == "win32":
        _set_windows_user_env(PROVIDER_ENV_KEY, api_key.strip())
    else:
        # 不再写入全局 OPENAI_API_KEY，避免 Claude Code/其他工具检测到系统环境变量冲突。
        # Codex 26.513+ 通过 ~/.codex/auth.json 读取 OPENAI_API_KEY；这里仅清理历史 auto++ 写入的 shell rc 块。
        rc_file = _detect_shell_rc()
        for env_key in ("OPENAI_API_KEY", PROVIDER_ENV_KEY):
            try:
                _remove_export_from_shellrc(rc_file, env_key)
            except IOError:
                pass

    # 生成模型目录 JSON
    write_model_catalog(login_info)

    # 写入 hooks.json
    configure_hooks_json(ahclaude_cmd)

    # 写入 config.toml provider 配置
    existing = load_toml_raw()
    cleaned = _remove_ahclaude_sections(existing)

    # 清理旧的 autohome provider 配置（含旧的 .auth 子节）
    cleaned = _remove_section(cleaned, f"[model_providers.{PROVIDER_ID}]")

    # Windows 路径转正斜杠，避免 TOML 解析失败（\U 被当作 unicode 转义）
    model_catalog_path = MODEL_CATALOG_FILE.replace("\\", "/") if sys.platform == "win32" else MODEL_CATALOG_FILE
    cleaned = _set_toplevel_keys(cleaned, {
        "model": model,
        "model_provider": PROVIDER_ID,
        "model_catalog_json": model_catalog_path,
        "model_reasoning_effort": "medium",
    })
    # disable_response_storage 是 TOML bool，不能用 _set_toplevel_keys（会加引号）
    if re.search(r'^disable_response_storage\s*=', cleaned, re.MULTILINE):
        cleaned = re.sub(r'^disable_response_storage\s*=.*$', 'disable_response_storage = true', cleaned, flags=re.MULTILINE)
    else:
        # 插到第一个 [section] 之前
        first_section = re.search(r'^\[', cleaned, re.MULTILINE)
        if first_section:
            cleaned = cleaned[:first_section.start()] + 'disable_response_storage = true\n' + cleaned[first_section.start():]
        else:
            cleaned = cleaned.rstrip('\n') + '\ndisable_response_storage = true\n'
    # codex_hooks 已废弃，清理旧配置，写入新的 hooks
    cleaned = _remove_section_key(cleaned, "[features]", "codex_hooks")
    cleaned = _set_section_bool_key(cleaned, "[features]", "hooks", True)

    from .config.api_config import BACKEND_API
    # Codex 26.513+ 使用 requires_openai_auth = true + auth.json，废弃 auth.command
    provider_block = f"""
[model_providers.{PROVIDER_ID}]
name = "{PROVIDER_NAME}"
base_url = "{BACKEND_API}/v1"
wire_api = "responses"
requires_openai_auth = true
"""

    new_content = cleaned.rstrip("\n") + "\n" + provider_block
    save_toml_raw(new_content)


def refresh_codex_config_after_model_select(login_info: dict):
    """模型切换后的 Codex 配置自愈入口。

    用户执行 `auto++ codex model` 时也要重写 hooks.json，避免用户删除/改坏 hook 后
    仍能继续使用但无法上报 start/prompt/stop/activate。
    """
    if not login_info.get("api_key"):
        raise RuntimeError("未检测到 Codex API key，请先执行 auto++ codex install 或重新登录")
    configure_codex(login_info)
    log_success("已刷新 Codex 配置和 hooks.json")


def install():
    print("=" * 50)
    print("auto++ 安装向导 (Codex)")
    print("=" * 50)
    print()

    try:
        print("[步骤 1/4] 初始化目录...")
        create_directory()

        print()
        print("[步骤 2/4] 读取认证信息...")
        login_info = ensure_auth()

        print()
        print("[步骤 3/4] 选择模型...")
        from . import cmd_codex_uninstall
        cmd_model.run_model_selector_interactive(
            login_info,
            reset_label="还原 Codex 默认配置",
            reset_uninstall_fn=cmd_codex_uninstall.uninstall,
            update_claude_settings=False,
            product="codex",
        )

        print()
        print("[步骤 4/4] 写入 Codex 配置...")
        configure_codex(login_info)

        print()
        print("=" * 50)
        log_success("安装完成!")
        print("=" * 50)
        print(f"  登录用户: {login_info['username']}")
        model_names = login_info.get("model_names", {})
        current_model = login_info['model']
        print(f"  当前模型: {model_names.get(current_model, current_model)}")
        print()
        print("请重启 Codex 以加载配置")
        print("首次加载后如果桌面端 Hooks 页面提示 review / trust，请手动信任 auto++ 安装的 hooks 并启用。")

    except KeyboardInterrupt:
        log_warning("\n安装已取消")
        sys.exit(1)
    except Exception as e:
        log_error(f"安装失败: {e}")
        sys.exit(1)
